mapper.select:
SELECT
  (SELECT COALESCE(SUM(o.receivable), 0) FROM sales_order o
    WHERE o.status <> '已作废'
    )                                    AS receivable,
  (SELECT COALESCE(SUM(o.received), 0) FROM sales_order o
    WHERE o.status <> '已作废'
    )                                    AS received,
  (SELECT COALESCE(SUM(-p.amount), 0) FROM payment p
    WHERE p.amount < 0
    )                                  AS refund,
  (SELECT COALESCE(SUM(o.debt), 0) FROM sales_order o
    WHERE o.status <> '已作废'
    )                                    AS debt,
  (SELECT COUNT(*) FROM sales_order o
    WHERE o.status <> '已作废'
    )                                    AS orderCount,
  (SELECT COUNT(*) FROM payment p
    WHERE 1 = 1
    )                                  AS paymentCount
